import { existsSync, mkdirSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import { type Page } from "@playwright/test";
import { test, expect, ready, activateAtStart, statusText, setSettings, extensionId } from "../e2e/extension";

// The store screenshots, regenerated by `npm run screenshots` from the
// comment-form fixture so a UI change is followed by matching PNGs. Each
// scene asserts that its PNG was written at the Web Store's 1280×800 and the
// Mode or content precondition its name states (NORMAL or VISUAL on the
// Status Line, the command line holding focus, the options page filled);
// what the picture shows beyond that is a reviewer's look, not a pixel
// comparison.

const storeDir = resolve("docs/store");

/** Width and height from the PNG's IHDR chunk, which follows the 8-byte signature and the chunk header. */
function pngSize(file: string): { width: number; height: number } {
  const png = readFileSync(file);
  return { width: png.readUInt32BE(16), height: png.readUInt32BE(20) };
}

async function shoot(page: Page, name: string): Promise<void> {
  mkdirSync(storeDir, { recursive: true });
  const file = resolve(storeDir, name);
  await page.screenshot({ path: file });
  expect(existsSync(file), `${name} written`).toBe(true);
  expect(pngSize(file), `${name} size`).toEqual({ width: 1280, height: 800 });
}

/** Opens the comment form Activated in Normal mode on the comment Field. */
async function openCommentForm(page: Page): Promise<void> {
  await page.goto("/comment-form.html");
  await ready(page);
  await activateAtStart(page, "#comment");
}

// The first key after Activation is never a vertical motion: the mirror is
// laid out off-screen, so CodeMirror keeps its estimated line heights until a
// key has been dispatched, and a first `j` on an unwrapped line longer than
// about 30 characters lands at the end of the text (a bridge gotcha found by
// this fixture; the e2e fixture's lines are too short to show it). The scenes
// park the cursor with `w` first.

test("1: Normal mode shown on the Status Line of the comment Field", async ({ page }) => {
  await openCommentForm(page);
  await page.keyboard.type("wjW");
  // The picture also shows the block cursor; the scene does not check it.
  expect(await statusText(page)).toContain("NORMAL");
  await shoot(page, "1-normal.png");
});

test("2: a Visual selection", async ({ page }) => {
  await openCommentForm(page);
  await page.keyboard.type("wjWv4e");
  expect(await statusText(page)).toContain("VISUAL");
  await shoot(page, "2-visual.png");
});

test("3: the command line holding a :s command, not yet entered", async ({ page }) => {
  await openCommentForm(page);
  await page.keyboard.type("wj:s/teh/the/");
  // Not entered: the typo is still there, and focus is in the Status Line
  // host, whose command-line input is its only focusable element (the mirror
  // is hidden). The document reports a focus inside a shadow root as its host.
  await expect(page.locator("#comment")).toHaveValue(/teh/);
  await expect(page.locator("vimtext-status")).toBeFocused();
  await shoot(page, "3-command-line.png");
});

test("4: the options page with the vimrc box and the Site Policy table", async ({ context, page }) => {
  await setSettings(context, {
    enabled: true,
    sites: {
      "https://github.com": "normal",
      "https://news.ycombinator.com": "normal",
      "https://mail.example.com": "off",
    },
    vimrc: "nnoremap Y y$\nnnoremap j gj\nnnoremap k gk\nmap <Space> :",
    plugins: { surround: true, targets: true },
  });
  await page.goto(`chrome-extension://${extensionId}/options/options.html`);
  await expect(page.locator("#sites tbody tr")).toHaveCount(3);
  await expect(page.locator("#vimrc")).toHaveValue(/nnoremap Y y\$/);
  await shoot(page, "4-options.png");
});
